-- Idempotent historical metadata copy; original runs are never changed.
INSERT OR IGNORE INTO owner_runs (id,player,name,received_at,played_at,build,map,source,device,difficulty,reason,t,score,replay,performance,country,environment) SELECT id,player,CASE WHEN json_type(json,'$.name')='text' AND length(json_extract(json,'$.name'))<=32 THEN json_extract(json,'$.name') END,CAST(round((julianday(received_at)-2440587.5)*86400000) AS INTEGER),played_at,build,
 CASE WHEN json_extract(json,'$.mapKey') IN ('old-town','rock-canyon') THEN json_extract(json,'$.mapKey') WHEN json_extract(json,'$.map.id')='rock_canyon_v1' OR json_extract(json,'$.mapVersion')='rock-canyon-v1' THEN 'rock-canyon' ELSE 'old-town' END,
 CASE WHEN json_extract(json,'$.source') IN ('github','y8') THEN json_extract(json,'$.source') ELSE 'unknown' END,
 CASE WHEN json_extract(json,'$.device') IN ('desktop','iphone','ipad','android') THEN json_extract(json,'$.device') WHEN input IN ('mouse','keyboard') THEN 'desktop' ELSE 'unknown' END,
 CASE WHEN json_type(json,'$.challenge.id') IS NULL THEN 'legacy' WHEN json_extract(json,'$.challenge.id') IN ('easy','normal','hard','expert','master','ultra','legacy') THEN json_extract(json,'$.challenge.id') ELSE 'unknown' END,reason,t,score,
 (COALESCE(json_array_length(json,'$.ghost.samples'),0)>=2 OR COALESCE(json_array_length(json,'$.trail'),0)>=2),
 CASE WHEN json_type(json,'$.performance.averageFps') IN ('integer','real') AND json_extract(json,'$.performance.averageFps') BETWEEN .1 AND 1000 THEN json_object('frameCount',CASE WHEN json_type(json,'$.performance.frameCount') IN ('integer','real','true','false') THEN json_extract(json,'$.performance.frameCount') END,'durationMs',CASE WHEN json_type(json,'$.performance.durationMs') IN ('integer','real','true','false') THEN json_extract(json,'$.performance.durationMs') END,'averageFps',CASE WHEN json_type(json,'$.performance.averageFps') IN ('integer','real','true','false') THEN json_extract(json,'$.performance.averageFps') END,'below30Count',CASE WHEN json_type(json,'$.performance.below30Count') IN ('integer','real','true','false') THEN json_extract(json,'$.performance.below30Count') END,'maxFrameMs',CASE WHEN json_type(json,'$.performance.maxFrameMs') IN ('integer','real','true','false') THEN json_extract(json,'$.performance.maxFrameMs') END,'ratio',CASE WHEN json_type(json,'$.performance.ratio') IN ('integer','real','true','false') THEN json_extract(json,'$.performance.ratio') END,'nativeRatio',CASE WHEN json_type(json,'$.performance.nativeRatio') IN ('integer','real','true','false') THEN json_extract(json,'$.performance.nativeRatio') END,'width',CASE WHEN json_type(json,'$.performance.width') IN ('integer','real','true','false') THEN json_extract(json,'$.performance.width') END,'height',CASE WHEN json_type(json,'$.performance.height') IN ('integer','real','true','false') THEN json_extract(json,'$.performance.height') END,'viewportWidth',CASE WHEN json_type(json,'$.performance.viewportWidth') IN ('integer','real','true','false') THEN json_extract(json,'$.performance.viewportWidth') END,'viewportHeight',CASE WHEN json_type(json,'$.performance.viewportHeight') IN ('integer','real','true','false') THEN json_extract(json,'$.performance.viewportHeight') END,'shadows',CASE WHEN json_type(json,'$.performance.shadows') IN ('integer','real','true','false') THEN json_extract(json,'$.performance.shadows') END,'quality',CASE WHEN json_extract(json,'$.performance.quality') IN ('auto','high','balanced','performance','minimum') THEN json_extract(json,'$.performance.quality') END) END,
 CASE WHEN json_extract(json,'$.country') GLOB '[A-Z][A-Z]' THEN json_extract(json,'$.country') END,
 json_object('os',CASE WHEN json_type(json,'$.environment.os')='text' AND length(json_extract(json,'$.environment.os'))<=64 THEN json_extract(json,'$.environment.os') END,'osVersion',CASE WHEN json_type(json,'$.environment.osVersion')='text' AND length(json_extract(json,'$.environment.osVersion'))<=64 THEN json_extract(json,'$.environment.osVersion') END,'browser',CASE WHEN json_type(json,'$.environment.browser')='text' AND length(json_extract(json,'$.environment.browser'))<=64 THEN json_extract(json,'$.environment.browser') END,'browserVersion',CASE WHEN json_type(json,'$.environment.browserVersion')='text' AND length(json_extract(json,'$.environment.browserVersion'))<=64 THEN json_extract(json,'$.environment.browserVersion') END,'model',CASE WHEN json_type(json,'$.environment.model')='text' AND length(json_extract(json,'$.environment.model'))<=64 THEN json_extract(json,'$.environment.model') END,'cores',CASE WHEN json_type(json,'$.environment.cores') IN ('integer','real') THEN json_extract(json,'$.environment.cores') END,'memoryGb',CASE WHEN json_type(json,'$.environment.memoryGb') IN ('integer','real') THEN json_extract(json,'$.environment.memoryGb') END,'screenWidth',CASE WHEN json_type(json,'$.environment.screenWidth') IN ('integer','real') THEN json_extract(json,'$.environment.screenWidth') END,'screenHeight',CASE WHEN json_type(json,'$.environment.screenHeight') IN ('integer','real') THEN json_extract(json,'$.environment.screenHeight') END,'nativeRatio',CASE WHEN json_type(json,'$.environment.nativeRatio') IN ('integer','real') THEN json_extract(json,'$.environment.nativeRatio') END)
 FROM runs WHERE julianday(received_at) IS NOT NULL AND length(player)<=64 AND player NOT GLOB '*[^a-zA-Z0-9_.-]*' AND player IS NOT NULL AND player!='anon' AND player!=''
 AND (build IS NULL OR build NOT LIKE '%-dev') AND COALESCE(json_extract(json,'$.channel'),'production')!='dev'
 AND COALESCE(json_extract(json,'$.kind'),'map')='map';
-- Link only sessions whose received run IDs resolve to exactly one player.
INSERT OR IGNORE INTO telemetry_players(session,player,name,received_at)
SELECT e.session,MIN(r.player),NULL,MIN(e.received_at)
FROM telemetry_events e JOIN owner_runs r ON r.id=e.run
GROUP BY e.session HAVING COUNT(DISTINCT r.player)=1;

-- Infer old source/device only when matching run events agree. Indexed by run.
UPDATE owner_runs SET source=COALESCE((SELECT MIN(source) FROM telemetry_events e WHERE e.run=owner_runs.id HAVING COUNT(DISTINCT source)=1),source)
WHERE source='unknown';
UPDATE owner_runs SET device=COALESCE((SELECT MIN(device) FROM telemetry_events e WHERE e.run=owner_runs.id HAVING COUNT(DISTINCT device)=1),device)
WHERE device='unknown';
